import{_ as t,o as a,c as n,ag as o}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"Regional Function Family proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/function/index.md","filePath":"proposals/function/index.md"}'),i={name:"proposals/function/index.md"};function r(s,e,c,d,l,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="regional-function-family-proposals" tabindex="-1">Regional Function Family proposals <a class="header-anchor" href="#regional-function-family-proposals" aria-label="Permalink to &quot;Regional Function Family proposals&quot;">​</a></h1><p>The Regional Function Family, <code>function.forms.takoform.com</code>, is one of the eight families of the v1 lineup (<a href="./../../spec/decisions/0043-forms-target-popular-vendor-locked-primitives.html">decision 0043</a>). Its members fix, completely, the application-visible semantics of the regional function-as-a-service model — an uploaded artifact, one declared handler, event-driven per-invocation execution — that every major cloud offers and no de-facto standard API covers, without naming any vendor (<a href="./../../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><h2 id="authoring-policy-shape-preserving-contracts" tabindex="-1">Authoring policy: shape-preserving contracts <a class="header-anchor" href="#authoring-policy-shape-preserving-contracts" aria-label="Permalink to &quot;Authoring policy: shape-preserving contracts&quot;">​</a></h2><p>Every member Form preserves one service shape end to end: execution ABI, invocation lifecycle, update and delete units, error semantics, and the capabilities a revision may reach. No free semantic token is admitted; a difference in semantics is a different Form, never a selector value. Outward capability use belongs to the revision resource; inward activation is an attachment resource (<a href="./../../spec/decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). Desired schemas carry no <code>name</code> or envelope plumbing: the resource envelope owns identity and status (<a href="./../../spec/decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>The family is minted after <a href="./../../spec/decisions/0045-external-standard-services-are-sealed-slots.html">decision 0045</a>, so its revision Form carries the external standard-service declaration from birth (<a href="./../../spec/standard-services/">spec/standard-services</a>): a Function Version reaches PostgreSQL, Redis, S3-compatible storage, or SMTP through sealed slots with opaque reverse-DNS protocol identifiers, never through endpoints or credentials in portable state.</p><p>These prose documents accompany four generated Experimental <code>0.x</code> candidates under <code>forms/candidates/function.forms.takoform.com</code>. The exact candidate set, Definitions, Interface digest, and packages — not proposal prose — own their current identities. Editing this directory reserves or changes no identity.</p><h2 id="the-function-aggregate" tabindex="-1">The function aggregate <a class="header-anchor" href="#the-function-aggregate" aria-label="Permalink to &quot;The function aggregate&quot;">​</a></h2><p>A Function has at most ONE FunctionDeployment; that deployment selects Function Versions of its own identity with basis-point weights summing to exactly 10000; every attachment is admitted against the deployment and refused when it is absent; and the identity reports itself Ready only while its deployment actually serves — the same aggregate statement the Edge family makes in <a href="./../../spec/decisions/0016-the-worker-aggregate-has-one-active-deployment.html">decision 0016</a>.</p><p>Cross-family event sources are not members of this family. An attachment that invokes a function from a queue, topic, a future source-specific object event contract, or a schedule is declared in the family that owns the SOURCE, exactly as the Edge family&#39;s <code>QueueConsumer</code> stays worker-targeted; scheduled invocation belongs to the separate current <code>schedule.forms.takoform.com</code> family. There is no current <code>ObjectBucket</code> Form or <code>edge.objects</code> Interface. The current Function family gives the function its own HTTP activation and nothing else.</p><h2 id="current-members" tabindex="-1">Current members <a class="header-anchor" href="#current-members" aria-label="Permalink to &quot;Current members&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Role</th><th>One-line semantics</th><th>Separate-Form boundary</th></tr></thead><tbody><tr><td><a href="./function.html">Function</a></td><td>identity</td><td>Logical identity of one regional JavaScript function; the ABI is fixed by identity.</td><td>A different language runtime, a WASI function, or a container service is a different Form.</td></tr><tr><td><a href="./function-version.html">FunctionVersion</a></td><td>revision</td><td>Immutable executable snapshot: artifact digest, handler, vars, sensitive slots, external services, memory/timeout/concurrency.</td><td>Mutable in-place code or config is not a version of this Form.</td></tr><tr><td><a href="./function-deployment.html">FunctionDeployment</a></td><td>deployment</td><td>Basis-point traffic shift between at most two Function Versions of one function.</td><td>Multi-alias routing or per-request rules are separate work.</td></tr><tr><td><a href="./function-endpoint.html">FunctionEndpoint</a></td><td>attachment</td><td>Delivers HTTPS requests at a host-assigned address as <code>http</code> invocation events.</td><td>An author-owned hostname or an access policy is a separate Form.</td></tr></tbody></table><p>Designs that differ in these semantics — other event sources, other runtimes, scheduled invocation — belong to other families or later members and get their own proposals when that work starts, per <a href="./../../spec/form-families.html">spec/form-families.md</a>.</p>',12)])])}const u=t(i,[["render",r]]);export{p as __pageData,u as default};
